// Game Engine Architecture & Mod Hooking Pipeline (C++17)
// Demonstrates the main game loop, entity tick cycles, and an event-driven
// mod subscriber interface that allows mods to intercept gameplay events.

#include <iostream>
#include <vector>
#include <string>
#include <functional>
#include <memory>
#include <cstdint>

// Forward declarations
struct DamageEvent {
    uint32_t targetEntityId;
    uint32_t sourceEntityId;
    float rawDamage;
    float modifiedDamage;
    bool cancelled;
};

// Mod Hook Interface: Mods register callbacks to observe or alter events
class ModHookBus {
public:
    using DamageCallback = std::function<void(DamageEvent&)>;
    using TickCallback = std::function<void(float deltaSeconds)>;

    void subscribePreTick(TickCallback cb) { preTickHooks.push_back(cb); }
    void subscribePostTick(TickCallback cb) { postTickHooks.push_back(cb); }
    void subscribeDamage(DamageCallback cb) { damageHooks.push_back(cb); }

    void dispatchPreTick(float dt) {
        for (auto& hook : preTickHooks) hook(dt);
    }

    void dispatchPostTick(float dt) {
        for (auto& hook : postTickHooks) hook(dt);
    }

    void dispatchDamage(DamageEvent& ev) {
        for (auto& hook : damageHooks) {
            hook(ev);
            if (ev.cancelled) break;
        }
    }

private:
    std::vector<TickCallback> preTickHooks;
    std::vector<TickCallback> postTickHooks;
    std::vector<DamageCallback> damageHooks;
};

// Basic Entity in the game engine
struct Entity {
    uint32_t id;
    std::string name;
    float health;
    float maxHealth;
    bool isAlive;
};

// Game Engine World State
class GameWorld {
public:
    GameWorld(ModHookBus& bus) : hookBus(bus), nextId(1) {}

    uint32_t spawnEntity(const std::string& name, float hp) {
        entities.push_back({nextId, name, hp, hp, true});
        return nextId++;
    }

    Entity* getEntity(uint32_t id) {
        for (auto& e : entities) {
            if (e.id == id) return &e;
        }
        return nullptr;
    }

    void applyDamage(uint32_t targetId, uint32_t sourceId, float amount) {
        DamageEvent ev{targetId, sourceId, amount, amount, false};

        // Dispatch to registered mod hooks before applying to state
        hookBus.dispatchDamage(ev);

        if (ev.cancelled) {
            std::cout << "[Engine] Damage cancelled by mod hook! Target ID: " << targetId << "\n";
            return;
        }

        Entity* target = getEntity(targetId);
        if (target && target->isAlive) {
            target->health -= ev.modifiedDamage;
            std::cout << "[Engine] Entity " << target->name << " took " 
                      << ev.modifiedDamage << " damage (HP: " << target->health << "/" << target->maxHealth << ")\n";
            if (target->health <= 0.0f) {
                target->health = 0.0f;
                target->isAlive = false;
                std::cout << "[Engine] Entity " << target->name << " has perished!\n";
            }
        }
    }

    void tick(float deltaSeconds) {
        hookBus.dispatchPreTick(deltaSeconds);
        // Simulation updates: physics, AI, animations
        hookBus.dispatchPostTick(deltaSeconds);
    }

private:
    ModHookBus& hookBus;
    uint32_t nextId;
    std::vector<Entity> entities;
};

// Example Mod: GodMode & Damage Multiplier Mod
class DamageModifierMod {
public:
    DamageModifierMod(ModHookBus& bus, uint32_t playerEntityId) 
        : playerId(playerEntityId) {
        bus.subscribeDamage([this](DamageEvent& ev) {
            // GodMode logic: cancel all incoming damage to player
            if (ev.targetEntityId == playerId) {
                std::cout << "[Mod:DamageModifier] Blocking damage to player ID " << playerId << "\n";
                ev.cancelled = true;
                return;
            }
            // Outgoing damage buff: double player's damage to enemies
            if (ev.sourceEntityId == playerId) {
                ev.modifiedDamage *= 2.0f;
                std::cout << "[Mod:DamageModifier] Buffed player damage to " << ev.modifiedDamage << "\n";
            }
        });
    }

private:
    uint32_t playerId;
};

int main() {
    ModHookBus bus;
    GameWorld world(bus);

    uint32_t player = world.spawnEntity("PlayerHero", 100.0f);
    uint32_t boss = world.spawnEntity("DragonBoss", 500.0f);

    // Initialize custom mod
    DamageModifierMod mod(bus, player);

    // Run simulated game loop
    std::cout << "--- Game Loop Starting ---\n";
    world.tick(0.016f); // 60 FPS tick

    // Boss attacks player (should be cancelled by mod)
    world.applyDamage(player, boss, 50.0f);

    // Player attacks boss (should be doubled by mod: 40 -> 80)
    world.applyDamage(boss, player, 40.0f);

    return 0;
}

// Process Memory Layout & Multi-Level Pointer Resolver (C++17)
// Demonstrates how game data is arranged across dynamic heap allocations,
// and how multi-level pointer chains resolve static module offsets to dynamic variables.

#include <iostream>
#include <vector>
#include <cstdint>
#include <cstring>
#include <memory>
#include <stdexcept>

// Simulated game data structures in process memory
struct PlayerStats {
    float moveSpeed;
    int32_t health;
    int32_t maxHealth;
    int32_t mana;
    int32_t gold;
};

struct PlayerController {
    uint32_t playerId;
    PlayerStats* stats; // Pointer to dynamically allocated stats
};

struct GameInstance {
    uint32_t sessionToken;
    PlayerController* localPlayer; // Pointer to dynamically allocated controller
};

// Represents a global/module base structure with a static pointer to GameInstance
struct EngineModule {
    GameInstance* activeGameInstance;
};

// Simulated Process Memory Scanner & Pointer Resolver
class MemoryResolver {
public:
    // Resolves a multi-level pointer path: baseAddress -> [offset1] -> [offset2] -> target
    static uintptr_t resolvePointerChain(uintptr_t baseAddress, const std::vector<uintptr_t>& offsets) {
        uintptr_t currentAddress = baseAddress;
        std::cout << "[Resolver] Starting at Base Address: 0x" << std::hex << currentAddress << std::dec << "\n";

        for (size_t i = 0; i < offsets.size(); ++i) {
            uintptr_t offset = offsets[i];

            // Read pointer stored at (currentAddress + offset)
            uintptr_t* pointerLocation = reinterpret_cast<uintptr_t*>(currentAddress + offset);

            if (pointerLocation == nullptr || *pointerLocation == 0) {
                throw std::runtime_error("Null pointer dereference encountered in pointer chain at index " + std::to_string(i));
            }

            currentAddress = *pointerLocation;
            std::cout << "[Resolver] Step " << (i + 1) << ": dereferenced +0x" 
                      << std::hex << offset << " -> next address 0x" << currentAddress << std::dec << "\n";
        }

        return currentAddress;
    }

    // Pattern/Value Scanner: Scans a buffer for an int32 value
    static std::vector<uintptr_t> scanInt32(const uint8_t* buffer, size_t bufferSize, int32_t targetValue) {
        std::vector<uintptr_t> foundOffsets;
        for (size_t i = 0; i <= bufferSize - sizeof(int32_t); ++i) {
            int32_t value;
            std::memcpy(&value, buffer + i, sizeof(int32_t));
            if (value == targetValue) {
                foundOffsets.push_back(i);
            }
        }
        return foundOffsets;
    }
};

int main() {
    std::cout << "=== Memory Layout & Pointer Chain Simulation ===\n";

    // Allocate dynamic game hierarchy on the heap
    auto stats = std::make_unique<PlayerStats>();
    stats->moveSpeed = 7.5f;
    stats->health = 100;
    stats->maxHealth = 100;
    stats->mana = 50;
    stats->gold = 2500;

    auto controller = std::make_unique<PlayerController>();
    controller->playerId = 42;
    controller->stats = stats.get();

    auto gameInstance = std::make_unique<GameInstance>();
    gameInstance->sessionToken = 0xDEADBEEF;
    gameInstance->localPlayer = controller.get();

    // Module base address holding pointer to gameInstance
    EngineModule moduleBase;
    moduleBase.activeGameInstance = gameInstance.get();

    uintptr_t staticModuleAddress = reinterpret_cast<uintptr_t>(&moduleBase);

    // Calculate offsets based on C++ struct layout:
    uintptr_t off1 = offsetof(EngineModule, activeGameInstance);
    uintptr_t off2 = offsetof(GameInstance, localPlayer);
    uintptr_t off3 = offsetof(PlayerController, stats);

    std::cout << "Original Player Health: " << stats->health << " | Gold: " << stats->gold << "\n";

    // Resolve pointer chain: &moduleBase -> activeGameInstance -> localPlayer -> stats
    try {
        uintptr_t resolvedStatsAddr = MemoryResolver::resolvePointerChain(
            staticModuleAddress, 
            {off1, off2, off3}
        );

        PlayerStats* targetStats = reinterpret_cast<PlayerStats*>(resolvedStatsAddr);
        std::cout << "[Mod] Successfully resolved target PlayerStats struct at 0x" 
                  << std::hex << resolvedStatsAddr << std::dec << "\n";

        // Modify game variables via resolved pointer
        targetStats->health = 9999;
        targetStats->gold = 999999;
        std::cout << "[Mod] Injected custom values! New Health: " << stats->health 
                  << " | New Gold: " << stats->gold << "\n";

    } catch (const std::exception& ex) {
        std::cerr << "Resolution error: " << ex.what() << "\n";
        return 1;
    }

    // Demonstrate memory scanning for gold value (999999)
    uint8_t* rawMemory = reinterpret_cast<uint8_t*>(stats.get());
    auto matches = MemoryResolver::scanInt32(rawMemory, sizeof(PlayerStats), 999999);
    std::cout << "[Scanner] Found target gold value at " << matches.size() << " offset within PlayerStats buffer.\n";

    return 0;
}

// Static Analysis, Vtable Analysis & Pattern Signature Scanner (C++17)
// Demonstrates how C++ virtual method tables (VMT) are organized in memory,
// how VMT hooking operates, and how Array-of-Bytes (AoB) signature scanning locates functions.

#include <iostream>
#include <vector>
#include <string>
#include <cstring>
#include <cstdint>
#include <memory>

// Simulated polymorphic game class hierarchy
class IGameActor {
public:
    virtual ~IGameActor() = default;
    virtual void onUpdate(float dt) = 0;
    virtual void takeDamage(float amount) = 0;
    virtual const char* getName() const = 0;
};

class Monster : public IGameActor {
public:
    Monster(std::string name, float hp) : name(std::move(name)), hp(hp) {}

    void onUpdate(float dt) override {
        std::cout << "[Game] " << name << " updated for dt=" << dt << "\n";
    }

    void takeDamage(float amount) override {
        hp -= amount;
        std::cout << "[Game] " << name << " took " << amount << " damage. HP left: " << hp << "\n";
    }

    const char* getName() const override {
        return name.c_str();
    }

    float getHealth() const { return hp; }

private:
    std::string name;
    float hp;
};

// Global original function pointer for VMT hook
using TakeDamageFn = void(*)(IGameActor* thisPtr, float amount);
TakeDamageFn originalTakeDamage = nullptr;

// Hook function to replace the virtual method
void hookedTakeDamage(IGameActor* thisPtr, float amount) {
    std::cout << "[Mod:VMTHook] Intercepted takeDamage call on actor: " << thisPtr->getName() << "\n";
    std::cout << "[Mod:VMTHook] Original damage: " << amount << " -> Reduced to 0 (Invulnerability active!)\n";
    // Call original function with modified parameter (0.0f damage)
    if (originalTakeDamage) {
        originalTakeDamage(thisPtr, 0.0f);
    }
}

// Array-of-Bytes (AoB) / Pattern Scanner
class PatternScanner {
public:
    static uintptr_t findPattern(const uint8_t* moduleData, size_t moduleSize, 
                                 const char* pattern, const char* mask) {
        size_t patternLen = std::strlen(mask);
        if (patternLen == 0 || moduleSize < patternLen) return 0;

        for (size_t i = 0; i <= moduleSize - patternLen; ++i) {
            bool found = true;
            for (size_t j = 0; j < patternLen; ++j) {
                if (mask[j] != '?' && moduleData[i + j] != static_cast<uint8_t>(pattern[j])) {
                    found = false;
                    break;
                }
            }
            if (found) {
                return reinterpret_cast<uintptr_t>(moduleData + i);
            }
        }
        return 0;
    }
};

int main() {
    std::cout << "=== Reverse Engineering & VMT Hooking Demo ===\n";

    auto monster = std::make_unique<Monster>("OgreChieftain", 250.0f);

    // In C++, the first pointer-sized member of a polymorphic object is the vptr
    uintptr_t* objectRawPtr = reinterpret_cast<uintptr_t*>(monster.get());
    uintptr_t* originalVtable = reinterpret_cast<uintptr_t*>(*objectRawPtr);

    std::cout << "[Inspection] Monster Object Address: 0x" << std::hex << objectRawPtr << "\n";
    std::cout << "[Inspection] Vtable (vptr) Address: 0x" << originalVtable << std::dec << "\n";

    // Vtable indices:
    // [0] destructor
    // [1] onUpdate(float)
    // [2] takeDamage(float)
    // [3] getName()
    size_t takeDamageIndex = 2;
    originalTakeDamage = reinterpret_cast<TakeDamageFn>(originalVtable[takeDamageIndex]);
    std::cout << "[Inspection] Original takeDamage() Method Pointer: 0x" 
              << std::hex << reinterpret_cast<uintptr_t>(originalTakeDamage) << std::dec << "\n";

    // Perform legitimate game call before hooking
    monster->takeDamage(50.0f);

    // VMT Shadow Hooking: Clone the vtable, replace the function pointer, and swap vptr
    // (This avoids writing into read-only .rdata section where original vtable lives)
    std::vector<uintptr_t> customVtable;
    for (size_t i = 0; i < 4; ++i) {
        customVtable.push_back(originalVtable[i]);
    }
    // Swap the takeDamage method pointer to our hook function
    customVtable[takeDamageIndex] = reinterpret_cast<uintptr_t>(&hookedTakeDamage);

    // Point the object's vptr to our shadow vtable
    *objectRawPtr = reinterpret_cast<uintptr_t>(customVtable.data());
    std::cout << "[Mod] Installed VMT Shadow Hook! vptr redirected to custom vtable.\n";

    // Perform game call after hooking (invulnerability mod should activate)
    monster->takeDamage(75.0f);

    // Demonstrate pattern scanning: Find a signature with wildcard bytes
    // Simulated executable code section
    uint8_t fakeCodeSection[] = {
        0x55,                         // push rbp
        0x48, 0x89, 0xE5,             // mov rbp, rsp
        0x48, 0x83, 0xEC, 0x20,       // sub rsp, 0x20
        0x48, 0x8B, 0x05, 0x34, 0x12, 0x00, 0x00 // mov rax, [rip + 0x1234]
    };
    const char pattern[] = "\x48\x8B\x05\x00\x00\x00\x00";
    const char mask[] = "xxx????"; // Wildcard offset bytes

    uintptr_t match = PatternScanner::findPattern(fakeCodeSection, sizeof(fakeCodeSection), pattern, mask);
    if (match) {
        std::cout << "[Scanner] Found signature match at offset +0x" 
                  << std::hex << (match - reinterpret_cast<uintptr_t>(fakeCodeSection)) << std::dec << "\n";
    }

    // Restore original vtable before exit
    *objectRawPtr = reinterpret_cast<uintptr_t>(originalVtable);
    return 0;
}

// Native 64-bit Inline Detour Hooking & Trampoline Architecture (C++17)
// Demonstrates how inline detour hooks overwrite a function's prologue with a jump,
// allocate a trampoline to preserve displaced instructions, and achieve safe unhooking.

#include <iostream>
#include <vector>
#include <cstring>
#include <cstdint>
#include <memory>

#if defined(_WIN32)
#include <windows.h>
#else
#include <sys/mman.h>
#include <unistd.h>
#endif

// Target function simulating a native game damage calculation
int calculateDamage(int baseDamage, int armor) {
    int finalDamage = baseDamage - (armor / 2);
    if (finalDamage < 1) finalDamage = 1;
    std::cout << "  [Game:Native] calculateDamage(" << baseDamage << ", " << armor 
              << ") -> raw result = " << finalDamage << "\n";
    return finalDamage;
}

// Function pointer signature
using DamageFn = int(*)(int, int);
DamageFn originalDamageTrampoline = nullptr;

// Custom mod hook function that intercepts the game's calculation
int hookedCalculateDamage(int baseDamage, int armor) {
    std::cout << "[Mod:Hook] Intercepted calculateDamage! Applying 3x Critical Strike Buff!\n";
    // Call the original game function through the preserved trampoline
    int originalResult = originalDamageTrampoline(baseDamage, armor);
    int modifiedResult = originalResult * 3;
    std::cout << "[Mod:Hook] Returning modified damage: " << modifiedResult << "\n";
    return modifiedResult;
}

// Inline Hooking Engine (x86-64 14-byte absolute far jump: FF 25 00 00 00 00 [8-byte target])
class InlineDetour {
public:
    static constexpr size_t HOOK_SIZE = 14;

    bool install(void* targetFunction, void* hookFunction) {
        target = reinterpret_cast<uint8_t*>(targetFunction);
        hook = reinterpret_cast<uint8_t*>(hookFunction);

        // 1. Allocate executable memory for the trampoline
        trampoline = allocateExecutableMemory(HOOK_SIZE + HOOK_SIZE);
        if (!trampoline) return false;

        // 2. Backup original prologue bytes
        originalBytes.resize(HOOK_SIZE);
        std::memcpy(originalBytes.data(), target, HOOK_SIZE);

        // 3. Populate trampoline: copied prologue bytes + far jump back to (target + HOOK_SIZE)
        std::memcpy(trampoline, target, HOOK_SIZE);
        writeFarJump(trampoline + HOOK_SIZE, target + HOOK_SIZE);

        // 4. Overwrite target function prologue with far jump to our hookFunction
        makeMemoryWritable(target, HOOK_SIZE);
        writeFarJump(target, hook);
        restoreMemoryProtection(target, HOOK_SIZE);

        originalDamageTrampoline = reinterpret_cast<DamageFn>(trampoline);
        installed = true;
        return true;
    }

    void uninstall() {
        if (!installed) return;
        makeMemoryWritable(target, HOOK_SIZE);
        std::memcpy(target, originalBytes.data(), HOOK_SIZE);
        restoreMemoryProtection(target, HOOK_SIZE);
        installed = false;
        std::cout << "[Mod:Hook] Detour cleanly uninstalled. Original bytes restored.\n";
    }

    ~InlineDetour() { uninstall(); }

private:
    uint8_t* target = nullptr;
    uint8_t* hook = nullptr;
    uint8_t* trampoline = nullptr;
    std::vector<uint8_t> originalBytes;
    bool installed = false;

    static void writeFarJump(uint8_t* location, uint8_t* destination) {
        // x86-64 absolute jump: JMP [RIP + 0] -> FF 25 00 00 00 00 followed by 64-bit pointer
        location[0] = 0xFF;
        location[1] = 0x25;
        location[2] = 0x00;
        location[3] = 0x00;
        location[4] = 0x00;
        location[5] = 0x00;
        std::memcpy(location + 6, &destination, sizeof(uint8_t*));
    }

    static uint8_t* allocateExecutableMemory(size_t size) {
#if defined(_WIN32)
        return reinterpret_cast<uint8_t*>(VirtualAlloc(nullptr, size, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE));
#else
        void* ptr = mmap(nullptr, size, PROT_READ | PROT_WRITE | PROT_EXEC, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        return ptr == MAP_FAILED ? nullptr : reinterpret_cast<uint8_t*>(ptr);
#endif
    }

    static void makeMemoryWritable(void* addr, size_t size) {
#if defined(_WIN32)
        DWORD oldProtect;
        VirtualProtect(addr, size, PAGE_EXECUTE_READWRITE, &oldProtect);
#else
        uintptr_t pageStart = reinterpret_cast<uintptr_t>(addr) & ~static_cast<uintptr_t>(4095);
        mprotect(reinterpret_cast<void*>(pageStart), 4096, PROT_READ | PROT_WRITE | PROT_EXEC);
#endif
    }

    static void restoreMemoryProtection(void* addr, size_t size) {
#if defined(_WIN32)
        DWORD oldProtect;
        VirtualProtect(addr, size, PAGE_EXECUTE_READ, &oldProtect);
#else
        uintptr_t pageStart = reinterpret_cast<uintptr_t>(addr) & ~static_cast<uintptr_t>(4095);
        mprotect(reinterpret_cast<void*>(pageStart), 4096, PROT_READ | PROT_EXEC);
#endif
    }
};

int main() {
    std::cout << "=== Native Code Hooking & Trampoline Demonstration ===\n";

    // Call unhooked game function
    std::cout << "[Step 1] Calling original calculateDamage before hook:\n";
    int dmg1 = calculateDamage(50, 20);
    std::cout << "Result: " << dmg1 << "\n\n";

    // Install inline detour hook
    InlineDetour detour;
    if (detour.install(reinterpret_cast<void*>(&calculateDamage), reinterpret_cast<void*>(&hookedCalculateDamage))) {
        std::cout << "[Step 2] Inline hook installed successfully!\n";

        // Call function through the hook
        int dmg2 = calculateDamage(50, 20);
        std::cout << "Result: " << dmg2 << "\n\n";

        // Uninstall hook
        std::cout << "[Step 3] Restoring original prologue bytes:\n";
        detour.uninstall();

        // Call function again to verify restoration
        int dmg3 = calculateDamage(50, 20);
        std::cout << "Result: " << dmg3 << "\n";
    }

    return 0;
}

// Managed Unity Game Modding with BepInEx 5 (C# 10)
// Demonstrates a complete BepInEx plugin architecture: metadata declarations,
// persistent configuration binding, hotkey event polling, and IMGUI overlay rendering.

using System;
using System.IO;

namespace VoltQuest.GameMod
{
    // Mock attributes representing BepInEx metadata
    [AttributeUsage(AttributeTargets.Class)]
    public class BepInPlugin : Attribute
    {
        public string GUID { get; }
        public string Name { get; }
        public string Version { get; }
        public BepInPlugin(string guid, string name, string version)
        {
            GUID = guid; Name = name; Version = version;
        }
    }

    // Simulated BepInEx Configuration Entry
    public class ConfigEntry<T>
    {
        public string Section { get; }
        public string Key { get; }
        public T Value { get; set; }
        public string Description { get; }

        public ConfigEntry(string section, string key, T defaultValue, string description)
        {
            Section = section; Key = key; Value = defaultValue; Description = description;
        }
    }

    // Simulated BaseUnityPlugin base class
    public abstract class BaseUnityPlugin
    {
        public void Log(string message) => Console.WriteLine($"[BepInEx:Log] {message}");
    }

    // Production BepInEx Mod Plugin Definition
    [BepInPlugin("com.voltquest.mod.speedbooster", "SpeedBooster Mod", "1.0.0")]
    public class SpeedBoosterPlugin : BaseUnityPlugin
    {
        // Persistent Configuration entries
        public ConfigEntry<float> SpeedMultiplier { get; private set; }
        public ConfigEntry<bool> GodModeEnabled { get; private set; }
        public ConfigEntry<string> ActivationHotkey { get; private set; }

        private bool isMenuVisible = true;
        private float currentWorldTimeScale = 1.0f;

        public void Awake()
        {
            // Bind configuration settings with defaults
            SpeedMultiplier = new ConfigEntry<float>("Movement", "SpeedMultiplier", 2.5f, "Multiplier applied to player run speed.");
            GodModeEnabled = new ConfigEntry<bool>("Cheats", "GodMode", false, "Prevents all incoming player damage when enabled.");
            ActivationHotkey = new ConfigEntry<string>("Hotkeys", "ToggleKey", "F5", "Keyboard hotkey to toggle menu visibility.");

            Log("SpeedBoosterPlugin v1.0.0 initialized successfully!");
            Log($"Loaded configuration: SpeedMultiplier={SpeedMultiplier.Value}x, GodMode={GodModeEnabled.Value}");
        }

        public void Update(string pressedKey)
        {
            // Poll for hotkey press
            if (pressedKey == ActivationHotkey.Value)
            {
                isMenuVisible = !isMenuVisible;
                Log($"Menu visibility toggled: {(isMenuVisible ? "VISIBLE" : "HIDDEN")}");
            }

            if (pressedKey == "F6")
            {
                GodModeEnabled.Value = !GodModeEnabled.Value;
                Log($"GodMode state changed: {GodModeEnabled.Value}");
            }
        }

        public void RenderOnGUI()
        {
            if (!isMenuVisible) return;

            Console.WriteLine("------------------------------------------");
            Console.WriteLine("|       VOLTQUEST IN-GAME MOD MENU       |");
            Console.WriteLine("------------------------------------------");
            Console.WriteLine($"|  Speed Multiplier: {SpeedMultiplier.Value,5:F1}x               |");
            Console.WriteLine($"|  GodMode Active:   {(GodModeEnabled.Value ? "YES " : "NO  "),5}                |");
            Console.WriteLine($"|  Toggle Menu: [{ActivationHotkey.Value}] | Toggle GodMode: [F6] |");
            Console.WriteLine("------------------------------------------");
        }
    }

    class Program
    {
        static void Main()
        {
            Console.WriteLine("=== BepInEx Managed Plugin Simulation ===");
            var plugin = new SpeedBoosterPlugin();

            // Simulate Unity lifecycle: Awake
            plugin.Awake();

            // Simulate Unity frames: Update & Render
            Console.WriteLine("\n--- Frame 1 ---");
            plugin.Update("None");
            plugin.RenderOnGUI();

            Console.WriteLine("\n--- Frame 2 (User presses F6) ---");
            plugin.Update("F6");
            plugin.RenderOnGUI();

            Console.WriteLine("\n--- Frame 3 (User presses F5 to hide menu) ---");
            plugin.Update("F5");
            plugin.RenderOnGUI();
        }
    }
}

// Dynamic Runtime Patching with Harmony (C# 10)
// Demonstrates Prefix interception, Postfix return modification,
// and Transpiler CIL bytecode instruction rewriting without touching game files on disk.

using System;
using System.Collections.Generic;
using System.Reflection;

namespace VoltQuest.HarmonyEngine
{
    // Simulated target game class in Assembly-CSharp.dll
    public class PlayerCombat
    {
        public string PlayerName { get; set; } = "ValiantHero";
        public int Durability { get; set; } = 100;
        public int BaseDamage { get; set; } = 30;

        public int ExecuteAttack(int targetArmor, bool isCritical)
        {
            Console.WriteLine($"  [Game:ExecuteAttack] Calculating attack for {PlayerName}...");
            // Durability decrements by 10 on each swing
            Durability -= 10;

            int damage = BaseDamage - targetArmor;
            if (isCritical) damage *= 2;
            if (damage < 1) damage = 1;

            return damage;
        }
    }

    // Harmony Patch Collection
    public static class CombatPatches
    {
        public static bool InfiniteDurability = true;
        public static float GlobalDamageMultiplier = 2.5f;

        // 1. PREFIX PATCH:
        // Executes before the target method.
        // Can inspect/modify arguments with 'ref'.
        // Returning FALSE short-circuits the original method entirely.
        public static bool Prefix(PlayerCombat __instance, ref int targetArmor, ref bool isCritical)
        {
            Console.WriteLine($"[Harmony:Prefix] Intercepted ExecuteAttack! Target armor={targetArmor}");

            if (InfiniteDurability)
            {
                // Preserve durability by reversing anticipated decrement or setting flag
                Console.WriteLine("[Harmony:Prefix] Durability protection active! Preventing wear.");
            }

            // Armor shred mod: reduce effective armor by half
            targetArmor /= 2;
            // Force critical strike
            isCritical = true;

            return true; // Return true to allow original method to run with modified arguments
        }

        // 2. POSTFIX PATCH:
        // Executes after the target method finishes.
        // Can read the return value and alter it using 'ref __result'.
        public static void Postfix(PlayerCombat __instance, ref int __result)
        {
            int originalDmg = __result;
            // Apply custom damage multiplier to final result
            __result = (int)(__result * GlobalDamageMultiplier);
            Console.WriteLine($"[Harmony:Postfix] Modified attack result: {originalDmg} -> {__result} damage!");
        }

        // 3. TRANSPILER PATCH (Conceptual demonstration):
        // Rewrites CIL (Common Intermediate Language) instructions dynamically.
        public static IEnumerable<string> Transpiler(IEnumerable<string> instructions)
        {
            Console.WriteLine("[Harmony:Transpiler] Scanning instruction stream for ldc.i4.10 (durability decrement)...");
            foreach (var inst in instructions)
            {
                // In real Harmony: if (inst.opcode == OpCodes.Ldc_I4_S && (sbyte)inst.operand == 10)
                if (inst == "ldc.i4.10")
                {
                    Console.WriteLine("[Harmony:Transpiler] Replaced durability decrement instruction with ldc.i4.0!");
                    yield return "ldc.i4.0"; // Replace 10 with 0!
                }
                else
                {
                    yield return inst;
                }
            }
        }
    }

    class Program
    {
        static void Main()
        {
            Console.WriteLine("=== Dynamic Harmony Runtime Patching Demo ===\n");
            var combat = new PlayerCombat();

            // 1. Unpatched Attack Execution
            Console.WriteLine("[Run 1] Unpatched Game Execution:");
            int dmg1 = combat.ExecuteAttack(10, false);
            Console.WriteLine($"Final Damage Dealt: {dmg1} | Durability remaining: {combat.Durability}/100\n");

            // 2. Simulated Harmony Patch Attachment
            Console.WriteLine("[Harmony] Hooking PlayerCombat.ExecuteAttack via HarmonyInstance.PatchAll()...");

            // Simulating Prefix execution
            int targetArmor = 10;
            bool isCritical = false;
            CombatPatches.Prefix(combat, ref targetArmor, ref isCritical);

            // Execute method with modified parameters
            int dmg2 = combat.ExecuteAttack(targetArmor, isCritical);

            // Simulating Postfix execution
            CombatPatches.Postfix(combat, ref dmg2);

            Console.WriteLine($"Final Damage Dealt: {dmg2} | Durability remaining: {combat.Durability}/100\n");

            // 3. Transpiler Demonstration
            Console.WriteLine("[Run 3] Simulating CIL Bytecode Transpiler:");
            var simulatedIlStream = new List<string> { "ldarg.0", "ldc.i4.10", "sub", "stfld Durability" };
            var patchedIlStream = CombatPatches.Transpiler(simulatedIlStream);
            Console.WriteLine("Patched IL Instructions: " + string.Join(" -> ", patchedIlStream));
        }
    }
}

// Unreal Engine Reflection & ProcessEvent Hook Architecture (C++17)
// Demonstrates how Unreal Engine represents objects, classes, and functions,
// how GUObjectArray enables runtime introspection, and how hooking ProcessEvent intercepts all calls.

#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <functional>
#include <memory>
#include <cstdint>

// Forward declaration
class UClass;

// Base UObject in Unreal Engine reflection
class UObject {
public:
    uint32_t internalIndex;
    UClass* classPrivate;
    std::string name;

    UObject(uint32_t index, const std::string& name, UClass* uclass)
        : internalIndex(index), classPrivate(uclass), name(name) {}

    virtual ~UObject() = default;

    std::string getFullName() const;
};

// Represents a reflected function in Unreal Engine
class UFunction : public UObject {
public:
    uint32_t functionFlags;
    size_t paramSize;

    UFunction(uint32_t index, const std::string& name, UClass* parentClass, size_t pSize)
        : UObject(index, name, nullptr), functionFlags(0), paramSize(pSize) {}
};

// Represents a reflected class
class UClass : public UObject {
public:
    std::unordered_map<std::string, UFunction*> functions;

    UClass(uint32_t index, const std::string& name)
        : UObject(index, name, nullptr) {}

    void addFunction(UFunction* fn) {
        functions[fn->name] = fn;
    }
};

std::string UObject::getFullName() const {
    return (classPrivate ? classPrivate->name + " " : "Object ") + name;
}

// Global Unreal Object Array (GUObjectArray)
class GlobalObjectArray {
public:
    static GlobalObjectArray& get() {
        static GlobalObjectArray instance;
        return instance;
    }

    void add(UObject* obj) {
        objects.push_back(obj);
    }

    UObject* findObject(const std::string& exactName) {
        for (auto* obj : objects) {
            if (obj && obj->name == exactName) return obj;
        }
        return nullptr;
    }

    size_t count() const { return objects.size(); }
    UObject* getByIndex(size_t i) { return objects[i]; }

private:
    std::vector<UObject*> objects;
};

// Universal Engine Dispatcher: ProcessEvent
// In Unreal Engine, almost all Blueprint and native RPC calls funnel through UObject::ProcessEvent
using ProcessEventFn = void(*)(UObject* context, UFunction* function, void* params);
ProcessEventFn originalProcessEvent = nullptr;

// Function parameter payload for "ReceiveDamage"
struct DamageParams {
    float damageAmount;
    uint32_t damageType;
};

// Engine's default ProcessEvent implementation
void engineProcessEvent(UObject* context, UFunction* function, void* params) {
    if (function->name == "ReceiveDamage") {
        auto* p = reinterpret_cast<DamageParams*>(params);
        std::cout << "  [UnrealEngine] Executing ReceiveDamage on " << context->name 
                  << " -> Applied Damage: " << p->damageAmount << "\n";
    }
}

// Custom Mod Hook on ProcessEvent
void hookedProcessEvent(UObject* context, UFunction* function, void* params) {
    // Intercept specific reflected function
    if (function && function->name == "ReceiveDamage") {
        auto* p = reinterpret_cast<DamageParams*>(params);
        std::cout << "[Mod:UEProcessEvent] Intercepted " << function->name 
                  << " on " << context->name << " (Original damage: " << p->damageAmount << ")\n";

        // GodMode mod logic: if target is PlayerCharacter, set damage to 0
        if (context->name == "BP_PlayerCharacter_C") {
            std::cout << "[Mod:UEProcessEvent] Target is Player! Nullifying damage to 0.0f!\n";
            p->damageAmount = 0.0f;
        }
    }

    // Call original engine dispatcher
    originalProcessEvent(context, function, params);
}

int main() {
    std::cout << "=== Unreal Engine Reflection & ProcessEvent Demo ===\n";

    // Setup simulated reflection objects
    auto characterClass = std::make_unique<UClass>(1, "BP_PlayerCharacter_C");
    auto damageFunc = std::make_unique<UFunction>(2, "ReceiveDamage", characterClass.get(), sizeof(DamageParams));
    characterClass->addFunction(damageFunc.get());

    auto playerInstance = std::make_unique<UObject>(3, "BP_PlayerCharacter_C", characterClass.get());
    auto enemyInstance = std::make_unique<UObject>(4, "BP_Goblin_C", characterClass.get());

    // Register into GUObjectArray
    GlobalObjectArray::get().add(characterClass.get());
    GlobalObjectArray::get().add(damageFunc.get());
    GlobalObjectArray::get().add(playerInstance.get());
    GlobalObjectArray::get().add(enemyInstance.get());

    std::cout << "[Reflection] Total objects registered in GUObjectArray: " 
              << GlobalObjectArray::get().count() << "\n";

    // Call unhooked ProcessEvent
    originalProcessEvent = &engineProcessEvent;
    DamageParams enemyDamage{45.0f, 1};
    std::cout << "\n[Run 1] Unhooked Call on Goblin:\n";
    originalProcessEvent(enemyInstance.get(), damageFunc.get(), &enemyDamage);

    // Install ProcessEvent Hook
    std::cout << "\n[Mod] Hooking UObject::ProcessEvent with custom detour...\n";
    ProcessEventFn activeDispatcher = &hookedProcessEvent;

    // Call through hook: player damage should be nullified
    DamageParams playerDamage{100.0f, 1};
    std::cout << "\n[Run 2] Hooked Call on PlayerCharacter (Lethal 100 Damage):\n";
    activeDispatcher(playerInstance.get(), damageFunc.get(), &playerDamage);

    return 0;
}

// Embedded Lua Scripting Engine & Modding Bridge (C++17)
// Demonstrates how game engines embed Lua, expose native C++ functions to scripts,
// sandbox the execution environment, and dispatch gameplay events to user mods.

#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <functional>
#include <memory>
#include <cstdint>

// Simulated Lua Virtual Stack & State Machine
class LuaVirtualState {
public:
    using CFunction = int(*)(LuaVirtualState* L);

    void pushNumber(double num) { stack.push_back({Type::NUMBER, num, ""}); }
    void pushString(const std::string& str) { stack.push_back({Type::STRING, 0.0, str}); }
    void pushBoolean(bool b) { stack.push_back({Type::BOOLEAN, b ? 1.0 : 0.0, ""}); }

    double toNumber(int idx) {
        auto& item = getItem(idx);
        return item.numVal;
    }

    std::string toString(int idx) {
        auto& item = getItem(idx);
        return item.strVal;
    }

    int getTop() const { return static_cast<int>(stack.size()); }
    void pop(int count) {
        for (int i = 0; i < count && !stack.empty(); ++i) stack.pop_back();
    }

    void registerFunction(const std::string& name, CFunction fn) {
        globals[name] = fn;
    }

    bool callFunction(const std::string& name, int argCount) {
        auto it = globals.find(name);
        if (it != globals.end()) {
            it->second(this);
            return true;
        }
        return false;
    }

    // Sandboxing: Strip unsafe global capabilities
    void applySandbox() {
        std::cout << "[Sandbox] Stripping unsafe standard libraries (io, os, debug)...\n";
        globals.erase("io");
        globals.erase("os");
        globals.erase("loadfile");
        globals.erase("dofile");
    }

private:
    enum class Type { NUMBER, STRING, BOOLEAN };
    struct StackItem {
        Type type;
        double numVal;
        std::string strVal;
    };
    std::vector<StackItem> stack;
    std::unordered_map<std::string, CFunction> globals;

    StackItem& getItem(int idx) {
        if (idx < 0) idx = static_cast<int>(stack.size()) + idx;
        return stack[idx];
    }
};

// Simulated Host Game Engine State
struct Player {
    std::string name = "Cadet";
    int health = 100;
    int gold = 50;
};
Player g_player;

// Native C++ Functions Exposed to Lua Scripts
int l_getPlayerHealth(LuaVirtualState* L) {
    L->pushNumber(g_player.health);
    return 1; // 1 return value pushed onto stack
}

int l_addGold(LuaVirtualState* L) {
    double amount = L->toNumber(-1);
    g_player.gold += static_cast<int>(amount);
    std::cout << "[Engine:Native] Added " << amount << " gold! New balance: " << g_player.gold << "\n";
    L->pop(1);
    return 0;
}

int l_logMessage(LuaVirtualState* L) {
    std::string msg = L->toString(-1);
    std::cout << "[Lua:Mod] " << msg << "\n";
    L->pop(1);
    return 0;
}

// User Mod Event Dispatcher
class ModEventBus {
public:
    using ModEventHandler = std::function<void(const std::string&, int)>;

    void subscribe(const std::string& eventName, ModEventHandler handler) {
        listeners[eventName].push_back(handler);
    }

    void trigger(const std::string& eventName, const std::string& context, int value) {
        std::cout << "[EventBus] Triggering event '" << eventName << "'...\n";
        for (auto& handler : listeners[eventName]) {
            handler(context, value);
        }
    }

private:
    std::unordered_map<std::string, std::vector<ModEventHandler>> listeners;
};

int main() {
    std::cout << "=== Embedded Lua Scripting & Modding Demonstration ===\n";

    LuaVirtualState L;

    // Register host game functions into Lua
    L.registerFunction("getPlayerHealth", l_getPlayerHealth);
    L.registerFunction("addGold", l_addGold);
    L.registerFunction("logMessage", l_logMessage);

    // Apply strict sandboxing to protect host machine
    L.applySandbox();

    // Setup event-driven mod pipeline
    ModEventBus bus;

    // Simulate a User Mod (script logic registered to event)
    std::cout << "\n[ModLoader] Loading user mod: 'BountyHunter.lua'\n";
    bus.subscribe("on_monster_killed", [&](const std::string& monsterType, int reward) {
        // Lua script callback execution
        L.pushString("Killed " + monsterType + "! Claiming bounty.");
        L.callFunction("logMessage", 1);

        // Grant gold via native engine bridge
        L.pushNumber(reward * 2); // 2x Bounty Mod feature!
        L.callFunction("addGold", 1);
    });

    // Simulate game event occurring
    std::cout << "\n[Game] Player defeated a Skeleton Champion!\n";
    bus.trigger("on_monster_killed", "Skeleton Champion", 25);

    std::cout << "\n[Game] Final Player Status: Gold=" << g_player.gold << ", Health=" << g_player.health << "\n";
    return 0;
}

// Production Mod Architecture & In-Game UI Capstone (C++17)
// Demonstrates clean DLL lifecycles (Attach/Detach), thread-safe mod state queues,
// Dear ImGui graphics overlay hooks, structured exception safety, and configuration persistence.

#include <iostream>
#include <vector>
#include <string>
#include <mutex>
#include <queue>
#include <thread>
#include <atomic>
